import type { ConsoleData } from "@oia/ingestion/console";
// Bundled at build time so it ships inside the Vercel serverless function and
// works identically locally. Regenerated by `pnpm --filter @oia/workers run m0:run`,
// which writes both outputs/milestone-0/console.json and this copy.
import bundled from "../data/console.json";

/**
 * Real Milestone-0 run output. No production Supabase: the console renders the
 * generated snapshot directly.
 */
export function loadConsoleData(): ConsoleData | null {
  return (bundled as unknown as ConsoleData) ?? null;
}
